'use strict';
(async function(){
const $=id=>document.getElementById(id),app=$('app'),dialog=$('dialog');
const e=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const enc=encodeURIComponent,fieldLabels={geography:'地理',history:'歴史',civics:'公民'},difficultyLabels={easy:'易しい',standard:'標準',hard:'難しい'},statusLabels={draft:'出題前の確認',lobby:'参加受付',opening:'オープニング',question:'相談・回答中',paused:'一時停止',closed:'回答締切',reveal:'正解・解説',ranking:'順位発表',ended:'ゲーム終了'};
let config={apiBase:'',publicFrontend:'https://masa0705u-wq.github.io/social-studies-quiz/'};try{config={...config,...await fetch(new URL('config.json',document.baseURI)).then(r=>r.json())};}catch{}
const base=config.apiBase.replace(/\/$/,'');
const teacherUrl=config.backendReady===false?'?view=teacher':(base||location.origin)+'/teacher';
const storage={get(k,f=null){try{return JSON.parse(localStorage.getItem('nazotoki:'+k))??f}catch{return f}},set(k,v){localStorage.setItem('nazotoki:'+k,JSON.stringify(v))},remove(k){localStorage.removeItem('nazotoki:'+k)}};
const query=new URLSearchParams(location.search),fragment=new URLSearchParams(location.hash.slice(1));
let role=query.get('view')||'home',tab='dashboard',catalog=null,game=null,session=storage.get('session'),teacherMeta=storage.get('teacherMeta',{}),selected=[],selectionOptions=null,selectionApproval=false,joinInfo=null,selectedGroup=null,bankFilter='',filterField='',filterApproval='',connection=true,serverOffset=0,lastStage='',audio=null,bgmTimer=null,muted=storage.get('muted',true),volume=storage.get('volume',.3),explanationStep=1,feedback='',currentGameId=storage.get('currentGameId'),polling=false;
if(fragment.get('game')){currentGameId=fragment.get('game');teacherMeta[currentGameId]={...(teacherMeta[currentGameId]||{}),projectorToken:fragment.get('token')};storage.set('teacherMeta',teacherMeta);history.replaceState(null,'',location.pathname+location.search);}
function toast(message,error=false){$('toast').textContent=message;$('toast').className=error?'error':'';$('toast').style.display='block';clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('toast').style.display='none',4500);}
async function api(action,input={}){const response=await fetch(base+'/api/quiz',{method:'POST',headers:{'Content-Type':'application/json'},credentials:base?'omit':'same-origin',body:JSON.stringify({action,input})});let data;try{data=await response.json()}catch{throw Error('サーバーに接続できません。再試行してください。')}if(!data.ok){const error=Error(data.message);error.code=data.code;throw error}return data.result;}
function button(label,action,args='',cls=''){return `<button type="button" class="btn ${cls}" data-action="${e(action)}" ${args}>${label}</button>`;}
function badge(q){return `<span class="badge ${e(q.difficulty)}">${e(difficultyLabels[q.difficulty])}</span> <span class="badge">${e(fieldLabels[q.field])}</span>`;}
function nav(){return `<header class="nav"><a href="${base?'./': '/portal.html'}" class="brand"><span class="brand-mark">?</span><span>社会科ナゾトキ教室<small>KNOWLEDGE MEETS DISCOVERY</small></span></a><nav class="nav-links"><a class="about-link" href="${config.publicFrontend}">ホーム</a>${role==='teacher'?`<span>先生用管理画面</span>`:`<a href="${teacherUrl}">先生はこちら</a>`}<button data-action="audio" title="音声切替">${muted?'♬ 音声オフ':'♬ 音声オン'}</button>${role==='home'?'<a class="join-link" href="?view=student">ゲームに参加 →</a>':''}</nav></header>`;}
function footer(){return `<footer class="footer"><span>社会科ナゾトキ教室 · 班で考える、みんなでひらめく。</span><a href="https://github.com/masa0705u-wq/social-studies-quiz" target="_blank" rel="noopener">GitHub ↗</a></footer>`;}
function shell(content,classes=''){app.innerHTML=nav()+(!connection?'<div class="connection-banner">通信が途切れています。入力内容を保持して再接続しています。</div>':'')+`<main class="${classes}">${content}</main>`+footer();hydrateImages();updateTimers();}
function renderHome(){shell(`<div class="wrap">${config.backendReady===false?'<div class="notice" style="margin-top:24px"><strong>画面プレビュー公開中</strong> · 回答保存・採点サーバーの公開作業が完了するまで、ゲームには参加できません。</div>':''}<section class="hero"><div><div class="eyebrow">中学校社会科 × 協力型ナゾトキ</div><h1>ひとりの知識が、<br>みんなの<span>ひらめき</span>に。</h1><p>地理・歴史・公民をめぐる、ちょっと不思議なクイズ。<br>班の仲間と話し合い、ヒントをつなぎ、答えを見つけよう。<br>いつもの教室が、10分間の冒険になる。</p><div class="hero-actions"><a class="btn orange" href="?view=student">ゲームに参加する <span>→</span></a><a class="btn light" href="${teacherUrl}">先生用画面を開く ↗</a></div><div class="hero-note"><span>生徒の登録不要</span><span>Chromebook対応</span><span>1班1台で参加</span></div></div><div class="scene" aria-label="地理・歴史・公民の知識をつなぐイラスト"><div class="orbit"></div><div class="globe"><i class="land a"></i><i class="land b"></i><i class="land c"></i></div><div class="paper-card geo"><span class="symbol">⌖</span><div>地理<small>世界を読み解く</small></div></div><div class="paper-card history"><span class="symbol">⌛</span><div>歴史<small>時代をつなぐ</small></div></div><div class="paper-card civics"><span class="symbol">⚖</span><div>公民<small>社会を考える</small></div></div><span class="star">✧</span><span class="scene-label">LET'S THINK TOGETHER.</span></div></section><section class="quick-facts"><div><strong>10–15<small>分</small></strong><p>授業のすきまに</p></div><div><strong>5–6<small>問</small></strong><p>班で解くチャレンジ</p></div><div><strong>3<small>分野</small></strong><p>地理・歴史・公民</p></div><div><strong>∞</strong><p>みんなのひらめき</p></div></section><div class="section-title"><div><small>CHOOSE YOUR ENTRANCE</small><h2>さあ、教室をはじめよう。</h2></div><p>準備は先生が。ひらめきはみんなで。</p></div><section class="role-grid"><a href="${teacherUrl}" class="role-card"><span class="role-icon">▤</span><div><h3>先生はこちら</h3><p>問題を選んで、ゲームを作成。<br>参加状況から正解発表まで、授業を進行できます。</p><span class="text-link">先生用画面を開く ↗</span></div></a><a href="?view=student" class="role-card student"><span class="role-icon">✦</span><div><h3>班のみんなはこちら</h3><p>先生の参加コードを入力したら、準備完了。<br>班の仲間と相談して、答えを送ろう。</p><span class="text-link">参加コードを入力する →</span></div></a></section><section class="how"><div><div class="eyebrow">HOW TO PLAY</div><h3>知っていることを、持ち寄ろう。</h3></div><p>① コードで参加　 →　 ② 班で相談　 →　 ③ 答えを送信<br>ヒント前の正解で満点。最後まで考え直すことができます。</p></section></div>`);}
function teacherTabs(){return `<div class="tabs">${[['dashboard','ホーム'],['new','ゲームを作る'],['bank','問題バンク'],['results','結果・履歴'],['settings','年度・設定'],['backup','バックアップ']].map(([id,label])=>`<button data-action="tab" data-tab="${id}" class="${tab===id?'active':''}">${label}</button>`).join('')}</div>`;}
async function loadTeacher(){try{await api('teacher.me');catalog=await api('catalog');if(currentGameId){try{game=await api('teacherState',{gameId:currentGameId});tab='game';}catch{}}renderTeacher();}catch(error){shell(`<div class="join-page"><div class="panel"><div class="eyebrow">TEACHER'S ROOM</div><h1>先生のログイン</h1><p class="muted">問題・正答・成績を守るため、登録された先生だけが操作できます。</p><a class="btn orange full-width" href="/signin-with-chatgpt?return_to=${enc('/teacher')}" target="_top">ChatGPTでログイン</a><p class="small-note">${e(error.message)}</p></div></div>`);}}
function renderTeacher(){if(tab==='game'&&game){renderGame();return;}shell(`<div class="wrap page"><div class="page-heading"><div><div class="eyebrow">TEACHER'S ROOM</div><h1>先生のコントロールルーム</h1><p>問題の準備から、最後のひらめきまで。</p></div><span class="badge-count">● サーバーで認証済み</span></div>${teacherTabs()}<div id="teacher-content">${teacherContent()}</div></div>`);}
function teacherContent(){const approved=catalog.questions.filter(q=>q.approvalStatus==='approved'&&!q.archived&&q.reuseEnabled).length;
 if(tab==='dashboard')return `<div class="grid3"><div class="stat"><label>出題できる問題</label><strong>${approved}<small> 問</small></strong><span class="small-note">教師が承認した問題のみ</span></div><div class="stat"><label>確認待ちの問題</label><strong>${catalog.questions.filter(q=>q.approvalStatus==='unreviewed'&&!q.archived).length}<small> 問</small></strong><span class="small-note">正答・出典・利用条件を確認</span></div><div class="stat"><label>登録済みクラス</label><strong>${catalog.years.reduce((s,y)=>s+y.classes.length,0)}<small> クラス</small></strong><span class="small-note">過年度の履歴も保持</span></div></div><div style="height:24px"></div><div class="grid2"><section class="panel"><div class="eyebrow">TODAY'S CHALLENGE</div><h2>今日のナゾトキを準備しよう。</h2><p class="muted">分野と難易度を選び、出題候補を確認。<br>班のみんなを迎える準備は、ここから。</p><div class="inline">${button('ゲームを作る →','tab','data-tab="new"','orange')}${currentGameId?button('前のゲームを再開','resumeGame','data-id="'+e(currentGameId)+'"','light'):''}</div></section><section class="panel"><h2>はじめて使う先生へ</h2><p class="muted">①「年度・設定」でクラスと班数を登録<br>②「問題バンク」で問題を登録・承認<br>③「ゲームを作る」で問題を選択</p>${button('年度・クラスを設定','tab','data-tab="settings"','light small')} ${button('問題を登録する','newQuestion','','light small')}</section></div><div class="notice">授業前に、学校のChromebookで参加・送信・投影表示を確認してください。出題時間によっては15分を超えることがあります。</div>`;
 if(tab==='new')return setupContent();if(tab==='bank')return bankContent();if(tab==='settings')return settingsContent();if(tab==='results')return '<div class="panel"><h2>ゲームの結果・履歴</h2><div id="results-list" class="loading">読み込み中…</div></div>';if(tab==='backup')return backupContent();return '';}
function setupContent(){const last=selectionOptions||catalog.lastGameSettings||{},year=catalog.years.find(y=>y.id===(last.yearId||catalog.activeYearId))||catalog.years.at(-1);return `<form id="game-setup"><div class="grid2"><section class="panel"><h2>ゲームの設定</h2><div class="inline" style="margin-bottom:20px">${button('10分復習','preset','data-preset="10"','light small')}${button('15分総合復習','preset','data-preset="15"','light small')}${button('前回の設定','preset','data-preset="last"','light small')}</div><div class="grid2"><label class="field">年度<select name="yearId" id="yearSelect">${catalog.years.map(y=>`<option value="${e(y.id)}" ${y===year?'selected':''}>${e(y.label)}</option>`).join('')}</select></label><label class="field">クラス<select name="classId" id="classSelect">${(year?.classes||[]).map(k=>`<option value="${e(k.id)}" ${last.classId===k.id?'selected':''}>${e(k.name)}</option>`).join('')}</select></label></div><label class="field">問題数<input name="count" type="number" min="1" max="20" value="${last.count||5}" required></label><label class="field">分野</label><div class="checkboxes">${Object.entries(fieldLabels).map(([id,label])=>`<label><input name="fields" type="checkbox" value="${id}" ${!last.fields?.length||last.fields.includes(id)?'checked':''}>${label}</label>`).join('')}</div><label class="field">単元（空欄なら全単元・複数はカンマ区切り）<input name="units" value="${e((last.units||[]).join(','))}" placeholder="日本の地域構成,江戸時代"></label><label class="field">難易度配分</label><div class="grid3">${[['easy','易しい',2],['standard','標準',2],['hard','難しい',1]].map(([id,label,n])=>`<label class="field">${label}<input type="number" min="0" max="20" name="${id}" value="${last.distribution?.[id]??n}" required></label>`).join('')}</div><label class="inline" style="margin-bottom:18px"><input type="checkbox" name="isSimulation">テスト実行（実績・正答率集計に含めない）</label><button class="btn orange full-width" ${year?'':'disabled'}>出題候補を選ぶ →</button>${!year?'<p class="small-note">先に年度・クラスを設定してください。</p>':''}</section><section class="panel"><h2>時間の目安</h2><p class="muted">易しい問題60秒・標準90秒・難しい問題120秒。ヒント後は獲得点が変わります。</p><div id="estimate" class="summary-list"></div><div class="notice">回答時間に、オープニング・解説・問題間の移行・順位発表を加えた見積もりです。授業の長さに合わせて調整できます。</div>${button('演出・解説時間を調整','tab','data-tab="settings"','light small')}</section></div></form><div id="selection">${selectionOptions?selectionContent():''}</div>`;}
function selectionContent(){const qs=selected;return `<section class="panel"><div class="section-title"><div><small>QUESTION PREVIEW</small><h2>出題候補を確認する</h2></div><span class="badge-count">${qs.length}問</span></div>${selectionApproval?'<div class="notice">条件に合う承認済み問題が不足しています。代替候補を選んだ場合は、下のチェックで条件変更を明示承認してください。</div>':''}${qs.map((q,i)=>`<div class="question-row"><span class="question-no">${i+1}</span><div style="flex:1">${badge(q)}<h3>${e(q.title)}</h3><p>${e(q.unit)}</p></div><div class="actions">${button('プレビュー','previewQuestion',`data-id="${e(q.questionId)}"`,'light small')}${button('↑','moveSelected',`data-index="${i}" data-dir="-1"`,'light small')}${button('↓','moveSelected',`data-index="${i}" data-dir="1"`,'light small')}${button('差し替え','replaceSelected',`data-index="${i}"`,'light small')}</div></div>`).join('')}<div class="inline" style="margin-top:20px"><label><input type="checkbox" id="alternative-approval"> 条件外の候補・難易度配分の変更を確認し、承認する</label></div><div class="inline" style="margin-top:20px">${button('この問題でゲームを作る →','createGame','','orange')}${button('候補を追加する','addSelected','','light')}</div><p class="small-note">承認済み・出題可の問題だけを選べます。正答・ヒント・画像・解説を必ず確認してください。</p></section>`;}
function bankContent(){const rows=catalog.questions.filter(q=>(!bankFilter||(q.title+' '+q.body+' '+q.unit).includes(bankFilter))&&(!filterField||q.field===filterField)&&(!filterApproval||q.approvalStatus===filterApproval));return `<section class="panel"><div class="section-title"><div><small>QUESTION BANK</small><h2>問題バンク</h2></div><div class="inline">${button('＋ 問題を登録','newQuestion','','orange')}${button('一括取込','importQuestions','','light')}</div></div><div class="grid3"><label class="field">キーワード<input id="bank-search" value="${e(bankFilter)}" placeholder="問題文・タイトル・単元を検索"></label><label class="field">分野<select id="bank-field"><option value="">すべて</option>${Object.entries(fieldLabels).map(([id,label])=>`<option value="${id}" ${filterField===id?'selected':''}>${label}</option>`).join('')}</select></label><label class="field">承認状態<select id="bank-approval"><option value="">すべて</option>${[['unreviewed','未確認'],['approved','承認済み'],['rejected','非承認']].map(([id,label])=>`<option value="${id}" ${filterApproval===id?'selected':''}>${label}</option>`).join('')}</select></label></div>${rows.length?rows.map(q=>{const stats=catalog.statistics?.[q.questionId];return `<div class="question-row"><div style="flex:1">${badge(q)} <span class="badge ${q.approvalStatus}">${e({unreviewed:'未確認',approved:'承認済み',rejected:'非承認'}[q.approvalStatus])}</span> ${q.archived?'<span class="badge">アーカイブ</span>':''}<h3>${e(q.title)}</h3><p>${e(q.unit)} · v${q.version}${stats?` · 最終正答率 ${Math.round(stats.finalRate*100)}% / ヒント前 ${Math.round(stats.preHintRate*100)}% · ${stats.denominator}班${stats.smallSample?'（少数サンプル）':''}`:' · 出題実績なし'}</p>${q.similarQuestionIds?.length?'<p>類似する文面・解法の候補があります。プレビューで確認してください。</p>':''}</div><div class="actions">${button('確認','previewQuestion',`data-id="${e(q.questionId)}"`,'light small')}${button('編集','editQuestion',`data-id="${e(q.questionId)}"`,'light small')}${button('複製','questionAction',`data-id="${e(q.questionId)}" data-command="duplicate"`,'light small')}${q.approvalStatus!=='approved'&&!q.archived?button('承認','questionAction',`data-id="${e(q.questionId)}" data-command="approve"`,'teal small'):''}${button(q.archived?'復帰':'保管','questionAction',`data-id="${e(q.questionId)}" data-command="${q.archived?'restore':'archive'}"`,'light small')}</div></div>`;}).join(''):'<div class="empty"><b>最初の問題を登録しよう。</b>個別登録またはJSON・CSVで取り込めます。<br>AIで作成した問題も、まず未確認として登録されます。</div>'}</section>`;}
function settingsContent(){const s=catalog.settings;return `<div class="grid2"><section class="panel"><h2>年度・クラス</h2>${catalog.years.map(y=>`<div class="question-row"><div><h3>${e(y.label)}</h3><p>${y.classes.map(k=>e(k.name)+'・'+k.groups.length+'班').join(' / ')}</p></div>${y.id===catalog.activeYearId?'<span class="badge approved">現在の年度</span>':button('この年度へ切替','activateYear',`data-id="${e(y.id)}"`,'light small')}</div>`).join('')}<h3 style="margin-top:25px">新しい年度を追加</h3><form id="year-form"><label class="field">年度名<input name="label" placeholder="2026年度" required maxlength="80"></label><div class="grid2"><label class="field">開始日<input name="startDate" type="date" required></label><label class="field">終了日<input name="endDate" type="date" required></label></div><label class="field">クラス名:班数（1行に1クラス）<textarea name="classes" placeholder="3年1組:8&#10;3年2組:8" required></textarea></label><button class="btn orange">年度・クラスを追加</button><p class="small-note">過年度のクラス・結果は残ります。個人名は登録しません。</p></form></section><section class="panel"><h2>時間・ヒント・音声の設定</h2><form id="settings-form"><div class="grid2">${[['openingSeconds','オープニング（秒）'],['explanationSeconds','解説1問あたり（秒）'],['transitionSeconds','問題間の移行（秒）'],['rankingSeconds','順位発表全体（秒）']].map(([id,label])=>`<label class="field">${label}<input type="number" name="${id}" min="0" max="300" value="${s[id]}" required></label>`).join('')}</div><h3>ヒントを出す残り秒数</h3><div class="grid3">${Object.entries(difficultyLabels).map(([d,label])=>`<label class="field">${label}<input type="number" min="0" max="${{easy:60,standard:90,hard:120}[d]}" name="hint-${d}" value="${s.hintRemainingSeconds[d]}" required></label>`).join('')}</div><label class="field">音量<input type="range" name="volume" min="0" max="1" step=".05" value="${s.volume}"></label><label class="inline"><input type="checkbox" name="muted" ${s.muted?'checked':''}>初期ミュート</label><div style="margin-top:20px"><button class="btn orange">設定を保存</button></div><p class="small-note">時間は見積もり用です。解説・次問は先生が操作します。既存ゲームの設定は作成時の状態を保持します。</p></form></section></div>`;}
function backupContent(){const s=catalog.settings;return `<div class="grid2"><section class="panel"><h2>バックアップと復元確認</h2><p class="muted">問題・ゲーム記録・回答履歴・設定・画像・参考資料を保存します。復元は隔離したテスト領域へ行い、本番データと照合します。</p>${button('今すぐバックアップ','backup','','orange')}<div id="backups-list" style="margin-top:20px">読み込み中…</div></section><section class="panel"><h2>自動バックアップの設定</h2><form id="backup-settings"><label class="inline"><input type="checkbox" name="backupEnabled" ${s.backupEnabled?'checked':''}>自動バックアップを有効にする</label><label class="field" style="margin-top:20px">実行間隔（時間）<input name="backupIntervalHours" type="number" min="1" max="168" value="${s.backupIntervalHours}"></label><label class="field">保存世代<input name="backupRetention" type="number" min="1" max="30" value="${s.backupRetention}"></label><button class="btn orange">設定を保存</button><p class="small-note">サーバーの定期処理が1時間ごとに期限を確認します。稼働確認結果は運用マニュアルを参照してください。</p></form><h3 style="margin-top:25px">資料ファイル</h3><p class="muted">参照中の資料・画像は削除できません。アーカイブや過去ゲームの参照も保護します。</p>${button('資料ファイルを管理','manageFiles','','light small')}</section></div>`;}
function openDialog(title,html){$('dialog-content').innerHTML=`<div class="dialog-head"><h2>${e(title)}</h2><button class="close" data-action="closeDialog" aria-label="閉じる">×</button></div>${html}`;if(!dialog.open)dialog.showModal();hydrateImages();}
function closeDialog(){dialog.close();}
function questionForm(q={}){const sources=(q.sources||[]).map(s=>JSON.stringify(s)).join('\n');openDialog(q.questionId?'問題を編集':'問題を登録',`<form id="question-form"><input type="hidden" name="questionId" value="${e(q.questionId||'')}"><label class="field">タイトル<input name="title" value="${e(q.title)}" required></label><label class="field">問題文<textarea name="body" required>${e(q.body)}</textarea></label><div class="grid3"><label class="field">分野<select name="field">${Object.entries(fieldLabels).map(([id,label])=>`<option value="${id}" ${q.field===id?'selected':''}>${label}</option>`).join('')}</select></label><label class="field">単元<input name="unit" value="${e(q.unit)}" required></label><label class="field">難易度<select name="difficulty">${Object.entries(difficultyLabels).map(([id,label])=>`<option value="${id}" ${q.difficulty===id?'selected':''}>${label}</option>`).join('')}</select></label></div><label class="field">謎解き形式<input name="puzzleType" value="${e(q.puzzleType||'deduction')}" required placeholder="deduction / classification / cipher"></label><label class="field">正答<input name="primaryAnswer" value="${e(q.primaryAnswer)}" required></label><label class="field">許容する別解（1行に1つ・単位や小数の表記違いも明示登録）<textarea name="acceptedAnswers">${e((q.acceptedAnswers||[]).join('\n'))}</textarea></label><label class="field">ヒント<textarea name="hintText" required>${e(q.hintText)}</textarea></label><label class="field">ヒントを出す残り秒数（空欄なら難易度別設定）<input type="number" min="0" max="120" name="hintThresholdSeconds" value="${q.hintThresholdSeconds??''}"></label><label class="field">段階的な解説（1行ごとに表示）<textarea name="explanation" required>${e(q.explanation)}</textarea></label><label class="field">出典（1行に1つのJSON）<textarea name="sources" required placeholder='{"title":"資料名","publisher":"発行者","url":"https://example.org/","retrievedAt":"2026-10-18","licenseNotes":"利用条件"}'>${e(sources)}</textarea></label><p class="small-note">未確認の出典は unverified:true を付け、捏造せず未確認と記録してください。参考資料ファイルは専用ファイル管理へ保存できます。</p><label class="inline"><input type="checkbox" name="reuseEnabled" ${q.reuseEnabled!==false?'checked':''}>出題に利用できる</label><div class="notice">新規・編集・複製した問題は未確認に戻ります。正答の一意性・出典・権利を確認してから承認してください。</div><button class="btn orange">未確認として保存</button></form>`);}
function previewQuestion(id,mode='teacher'){const q=catalog.questions.find(q=>q.questionId===id)||selected.find(q=>q.questionId===id);if(!q)return;openDialog(q.title,`<div class="inline">${button('先生向け','questionPreviewMode',`data-id="${e(id)}" data-mode="teacher"`,'light small')}${button('生徒プレビュー','questionPreviewMode',`data-id="${e(id)}" data-mode="student"`,'light small')}${button('投影プレビュー','questionPreviewMode',`data-id="${e(id)}" data-mode="projector"`,'light small')}</div><div style="margin-top:20px">${badge(q)}<h2 style="line-height:1.8;white-space:pre-wrap">${e(q.body)}</h2>${mode!=='student'?images(q.images,'teacher'):''}${mode==='teacher'?`<div class="subheading">正答・別解</div><div class="reveal-answer">${e(q.primaryAnswer)}</div><p class="muted">${e(q.acceptedAnswers.join(' / '))}</p><div class="hint"><small>HINT</small>${e(q.hintText)}</div><div class="subheading">解説</div><p class="explanation">${e(q.explanation)}</p><div class="subheading">出典</div>${q.sources.map(s=>`<p class="small-note">${e(s.title)} / ${e(s.publisher)} / ${e(s.retrievedAt)}<br>${e(s.url||s.driveFileId||'未確認')}<br>${e(s.licenseNotes)}</p>`).join('')}<div class="subheading">類似候補・使用履歴</div><p class="small-note">類似候補ID: ${e((q.similarQuestionIds||[]).join(', ')||'なし')}<br>出題を受けた班数: ${catalog.statistics?.[id]?.denominator??0}班</p><div class="inline">${button('画像を管理','questionImages',`data-id="${e(id)}"`,'light small')}${button('編集','editQuestion',`data-id="${e(id)}"`,'light small')}${q.approvalStatus!=='approved'?button('確認して承認','questionAction',`data-id="${e(id)}" data-command="approve"`,'teal small'):button('非承認に変更','questionAction',`data-id="${e(id)}" data-command="reject"`,'light small')}</div>`:`<p class="small-note">${mode==='student'?'回答欄はゲーム開始後に表示されます。':'画像はクリックで拡大できます。'}</p>`}</div>`);}
function images(list,access){return `<div class="images">${(list||[]).map(i=>`<div class="image-box" data-image="${e(i.fileId)}" data-access="${access}"><span class="small-note">画像を読み込み中…</span></div>`).join('')}</div>`;}
const imageCache=new Map();async function hydrateImages(){for(const target of document.querySelectorAll('[data-image]')){const id=target.dataset.image,access=target.dataset.access;if(target.dataset.loaded)continue;target.dataset.loaded='1';try{const cacheKey=access+':'+id+':'+(game?.round?.id||'');let src=imageCache.get(cacheKey);if(!src){const result=await api(access==='teacher'?'teacherImage':'image',{fileId:id,gameId:currentGameId,token:teacherMeta[currentGameId]?.projectorToken});src=result.data;imageCache.set(cacheKey,src);}if(target.isConnected){target.innerHTML=`<img alt="問題資料画像" src="${e(src)}" data-action="zoomImage">`;}}catch{target.textContent='画像を取得できません。先生に確認してください。';}}}
function renderJoin(){if(session){renderStudentWaiting();return;}shell(`<div class="join-page"><div class="eyebrow">TEAM ENTRANCE</div><h1>班のみんなで、参加しよう。</h1><p class="muted">先生から伝えられた6桁のコードを入力してください。</p><section class="panel"><form id="join-code-form"><label class="field">参加コード<input class="join-code" name="code" inputmode="numeric" pattern="[0-9]{6}" maxlength="6" placeholder="000000" value="${e(joinInfo?.code||'')}" required autocomplete="off"></label><button class="btn orange full-width">班を選ぶ →</button></form>${joinInfo?`<div class="subheading">${e(joinInfo.className)}・班を選んでください</div><div class="group-grid">${joinInfo.groups.map(g=>`<button class="group-choice ${selectedGroup===g.id?'selected':''}" data-action="selectGroup" data-id="${e(g.id)}" aria-pressed="${selectedGroup===g.id}" ${g.joined?'disabled':''}>${e(g.name)}${g.joined?'<small style="display:block;margin-top:5px">参加済み</small>':''}</button>`).join('')}</div><p class="small-note">クラスと班を確認してから参加してください。参加済みの場合は先生に端末の再割当てを依頼します。</p>${button('この班で参加する','joinGroup','','teal full-width')}`:''}</section><p class="small-note">1班につき1台で操作します。氏名・メールアドレスの入力は不要です。</p></div>`);}
function renderStudentWaiting(){shell(`<div class="join-page"><section class="panel waiting"><span class="badge">${e(session.groupName)}</span><h1>先生のスタートを待とう。</h1><p class="muted">班の仲間と準備してお待ちください。</p>${button('参加情報を確認し直す','leaveSession','','light small')}</section></div>`);}
function timerMarkup(clock){return clock?`<div class="timer" data-deadline="${clock.deadlineAt}" data-paused="${clock.status==='paused'?clock.remainingMsOnPause:''}" data-total="${{easy:60,standard:90,hard:120}[game.round.difficulty]*1000}" data-closed="${['closed','reveal','ranking','ended'].includes(game.status)}">--:--</div><div class="progress"><span id="time-progress"></span></div>`:'';}
function roundContent(){const r=game.round;if(!r)return '';const reveal=['reveal','ranking','ended'].includes(game.status);return `<div class="inline"><span class="badge ${e(r.difficulty)}">${e(difficultyLabels[r.difficulty])}</span><span class="muted">第${game.index+1}問 / 全${game.questionCount}問</span></div><h2>${e(r.body)}</h2>${role==='student'?'':images(r.images,role==='teacher'?'teacher':'projector')}${r.hint?`<div class="hint"><small>HINT · ヒント</small>${e(r.hint)}</div>`:''}${reveal?`<div class="subheading">ANSWER · 正答</div><div class="reveal-answer">${e(r.primaryAnswer)}</div><div class="explanation">${e(r.explanation.split('\n').slice(0,game.explanationStep||1).join('\n'))}</div>`:''}`;}
function scoresContent(){return `<div class="group-status">${game.groups.filter(g=>g.joined||game.scores.some(s=>s.groupId===g.id)).map(group=>{const answer=game.round?.answered.includes(group.id),result=game.round?.results?.[group.id],score=game.scores.find(s=>s.groupId===group.id);return `<span class="group-pill ${answer?'answered':''}"><span>${e(group.name)}</span><strong>${result?result.answered===false?'—':result.isCorrect?'○':'×':answer?'✓':'·'}</strong><span>${score?.totalPoints??0}点</span></span>`;}).join('')}</div>`;}
function renderGame(){if(!game)return;const previousRound=$('answer-form')?.dataset.round,previousFocus=document.activeElement?.id,previousValue=previousFocus==='student-answer'?document.activeElement.value:null,selectionStart=previousFocus==='student-answer'?document.activeElement.selectionStart:null;
 if(role==='teacher'){const meta=teacherMeta[game.id]||{};const controls=[];const st=game.status;
 if(st==='draft')controls.push(button('参加受付を開く','command','data-command="open"','orange'));
 if(st==='lobby')controls.push(button('オープニング開始','command','data-command="start"','orange'));
 if(st==='opening')controls.push(button('演出をスキップ','command','data-command="skipOpening"','orange'));
 if(st==='question')controls.push(button('一時停止','command','data-command="pause"','light'),button('30秒延長','command','data-command="extend" data-seconds="30"','light'),button('回答を締め切る','command','data-command="close"','orange'));
 if(st==='paused')controls.push(button('再開','command','data-command="resume"','orange'),button('30秒延長','command','data-command="extend" data-seconds="30"','light'),button('回答を締め切る','command','data-command="close"','light'));
 if(st==='closed')controls.push(button('正解を発表する','command','data-command="reveal"','orange'));
 if(st==='reveal')controls.push(button('解説を進める','command','data-command="explainNext"','light'),button(game.index+1<game.questionCount?'次の問題へ →':'最終順位を発表 →','command','data-command="next"','orange'));
 if(st==='ranking')controls.push(button('順位発表をスキップ','command','data-command="skipRanking"','orange'));
 shell(`<div class="wrap page"><div class="page-heading"><div><div class="eyebrow">LIVE CONTROL</div><h1>${e(game.className)}のナゾトキ</h1><p>${e(statusLabels[st])} · ${e(game.yearLabel)}</p></div><div class="inline">${button('ホームへ','tab','data-tab="dashboard"','light small')}<span class="connected"><i class="dot online"></i>接続中</span></div></div><div class="live-layout"><div><section class="panel live-question">${['draft','lobby'].includes(st)?`<div class="eyebrow">JOIN CODE</div><h2>班のみんなを迎えよう。</h2><div class="code-display">${e(meta.joinCode||'再発行が必要')}</div><div class="inline"><a class="btn light small" href="${config.publicFrontend}?view=student" target="_blank" rel="noopener">生徒の参加画面 ↗</a>${button('参加コード再発行','renewCode','','light small')}${meta.projectorToken?`<a class="btn light small" href="${config.publicFrontend}?view=projector#game=${enc(game.id)}&token=${enc(meta.projectorToken)}" target="_blank" rel="noopener">投影画面を開く ↗</a>`:button('投影リンク再発行','renewProjection','','light small')}</div><div class="subheading">参加状況 ${game.groups.filter(g=>g.joined).length}/${game.groups.length}班</div><div class="group-status">${game.groups.map(g=>`<span class="group-pill ${g.joined?'answered':''}"><i class="dot ${g.connected?'online':''}"></i>${e(g.name)} ${g.joined?'参加済':'未参加'} ${g.joined?`<button data-action="reassign" data-id="${e(g.id)}" class="close" style="width:22px;height:22px;font-size:11px" title="端末を解除">×</button>`:''}</span>`).join('')}</div><p class="small-note">全班参加前でも先生の判断で開始できます。未参加班は出題時の正答率の分母に含みません。</p>${st==='draft'?game.rounds.map((r,i)=>`<div class="question-row"><div><span class="badge">第${i+1}問</span><h3>${e(r.question.title)}</h3></div>${button('内容を確認','previewGameRound',`data-index="${i}"`,'light small')}</div>`).join(''):''}`:st==='opening'?`<div class="waiting"><div class="eyebrow">LET'S THINK TOGETHER</div><h2>ひらめきを、つなごう。</h2><div class="big" data-opening="${game.openingUntil}">—</div></div>`:['ranking','ended'].includes(st)?rankingContent():roundContent()}<div class="inline" style="margin-top:24px">${controls.join('')}</div></section>${!['draft','lobby','opening','ranking','ended'].includes(st)?`<section class="panel"><h2>班の回答と救済操作</h2><div class="table-scroll"><table><thead><tr><th>班</th><th>最終受理回答</th><th>受理時刻</th><th>今回得点</th><th>操作</th></tr></thead><tbody>${game.groups.map(g=>{const r=game.responses?.[g.id]?.latest,s=game.round?.results?.[g.id];return `<tr><td>${e(g.name)}</td><td>${e(r?.answerRaw||'未回答')}</td><td>${r?new Date(r.serverReceivedAt).toLocaleTimeString('ja-JP',{timeZone:'Asia/Tokyo'}):'—'}</td><td>${s?.points??'—'}</td><td>${button('代理回答','proxy',`data-id="${e(g.id)}"`,'light small')} ${button('採点修正','override',`data-id="${e(g.id)}"`,'light small')}${button('端末解除','reassign',`data-id="${e(g.id)}"`,'light small')}</td></tr>`;}).join('')}</tbody></table></div></section>`:''}</div><aside><section class="panel"><h3>サーバー基準の残り時間</h3>${timerMarkup(game.round?.clock)}<p class="small-note">一時停止・延長は全端末に反映されます。</p></section><section class="panel"><h3>班ごとの累計点</h3>${scoresContent()}<p class="small-note">ゲーム中は順位を表示しません。</p></section>${button('監査・回答履歴','gameHistory','','light full-width')}</aside></div></div>`);
 }else if(role==='projector'){const st=game.status;shell(`<div class="projector"><div class="projector-top"><div><span class="eyebrow" style="color:#a9c8ba">TEAM QUIZ CHALLENGE</span><div>${e(game.className)} · ${e(statusLabels[st])}</div></div><div>${timerMarkup(game.round?.clock)}</div></div>${['draft','lobby'].includes(st)?'<div class="waiting"><h1>仲間と相談して、答えを見つけよう。</h1><p class="muted">先生の合図を待ってください。</p></div>':st==='opening'?`<div class="waiting"><h1>社会科ナゾトキ、スタート！</h1><div class="big" data-opening="${game.openingUntil}">—</div></div>`:['ranking','ended'].includes(st)?rankingContent():`<div class="inline"><span class="badge">第${game.index+1}問 / 全${game.questionCount}問</span><span class="badge ${game.round.difficulty}">${e(difficultyLabels[game.round.difficulty])}</span></div><h1>${e(game.round.body)}</h1>${images(game.round.images,'projector')}${game.round.hint?`<div class="hint"><small>HINT</small>${e(game.round.hint)}</div>`:''}${st==='reveal'?`<div class="reveal-answer">${e(game.round.primaryAnswer)}</div><div class="explanation">${e(game.round.explanation.split('\n').slice(0,game.explanationStep||1).join('\n'))}</div>`:''}${st==='closed'?'<p class="muted">回答を締め切りました。正解発表を待とう。</p>':''}`}${scoresContent()}<div class="inline" style="justify-content:flex-end">${button('全画面表示','fullscreen','','light small')}</div></div>`);
 }else{const st=game.status;let body;if(['lobby','draft','opening'].includes(st)){body=`<div class="waiting"><h2>${st==='opening'?'もうすぐスタート！':'先生のスタートを待とう。'}</h2><p class="muted">班の仲間と話し合う準備をしよう。</p>${st==='opening'?`<div class="big" data-opening="${game.openingUntil}">—</div>`:''}</div>`;}else if(['ranking','ended'].includes(st))body=rankingContent();else{const active=st==='question',draft=storage.get('draft:'+game.round.id,game.myAnswer?.answerRaw||'');body=roundContent()+`<div style="margin-top:25px">${timerMarkup(game.round.clock)}</div>${active||st==='paused'?`<form id="answer-form" class="answer-area" data-round="${e(game.round.id)}"><label class="field" style="margin-top:24px">班の答え<textarea id="student-answer" maxlength="2000" placeholder="相談して決めた答えを入力" ${active?'':'disabled'} required>${e(draft)}</textarea></label><button class="btn orange full-width" id="send-answer" ${active?'':'disabled'}>${game.myAnswer?'答えを変更して送信':'答えを送信する'} →</button><div class="answer-state ${feedback.startsWith('失敗')?'error':''}" id="answer-status" role="status">${e(feedback|| (game.myAnswer?'サーバー受理済み：'+new Date(game.myAnswer.serverReceivedAt).toLocaleTimeString('ja-JP',{timeZone:'Asia/Tokyo'}):st==='paused'?'先生が一時停止しています。':'締切までは何度でも送信できます。'))}</div></form>`:`<div class="notice">${st==='closed'?'回答を締め切りました。先生の正解発表を待とう。':'班のみんなで解説を確認しよう。'}</div>`}`;}
 shell(`<div class="wrap page" style="max-width:850px"><div class="page-heading"><div><span class="badge approved">${e(session.groupName)}</span><h1 style="margin-top:12px">${e(game.className)}のナゾトキ</h1></div><span class="connected"><i class="dot online"></i>接続中</span></div><section class="panel live-question">${body}</section>${scoresContent()}${button('参加情報を確認し直す','leaveSession','','light small')}</div>`);if(previousFocus==='student-answer'&&previousRound===game.round?.id&&$('student-answer')){$('student-answer').value=previousValue;$('student-answer').focus();$('student-answer').setSelectionRange(selectionStart,selectionStart);}}
 playEvents();}
function rankingContent(){return `<div class="waiting" style="padding:20px 0"><div class="eyebrow">TEAM RESULTS</div><h2>${game.status==='ended'?'みんなのひらめきに、拍手！':'順位を発表します。'}</h2><p class="muted">同点は同じ順位。力を合わせた、今日の結果。</p></div>${(game.ranking||[]).map(r=>`<div class="rank-row ${r.rank===1?'winner':''}"><span class="rank-number">${r.rank}</span><strong>${e(r.name)}${r.rank===1?' ✦':''}</strong><span class="points">${r.totalPoints}<small> 点</small></span></div>`).join('')}${game.status==='ended'?`<div class="subheading">問題を振り返ろう</div>${(game.review||[]).map((r,i)=>`<details class="panel"><summary>第${i+1}問　${e(r.title)}</summary><p class="muted">${e(r.body)}</p><strong>${e(r.answer)}</strong><p class="explanation">${e(r.explanation)}</p></details>`).join('')}`:''}`;}
async function refreshCatalog(){catalog=await api('catalog');}
function updateEstimate(){const form=$('game-setup');if(!form)return;const n=d=>Number(form.elements[d].value||0);const answer=n('easy')*60+n('standard')*90+n('hard')*120,count=n('count'),s=catalog.settings;const explanation=count*s.explanationSeconds,other=s.openingSeconds+Math.max(0,count-1)*s.transitionSeconds+s.rankingSeconds,total=answer+explanation+other;$('estimate').innerHTML=[['回答時間',answer],['解説',explanation],['演出・移行',other],['合計',total]].map(([label,seconds])=>`<div>${label}<strong>${Math.floor(seconds/60)}分${seconds%60}秒</strong></div>`).join('');}
async function loadAuxiliary(){if(tab==='new')updateEstimate();if(tab==='results'){const results=await api('results');if(!$('results-list'))return;$('results-list').innerHTML=results.length?`<div class="table-scroll"><table><thead><tr><th>日時</th><th>年度・クラス</th><th>状態</th><th>操作</th></tr></thead><tbody>${results.reverse().map(r=>`<tr><td>${new Date(r.createdAt).toLocaleString('ja-JP',{timeZone:'Asia/Tokyo'})}</td><td>${e(r.yearLabel)} ${e(r.className)}</td><td>${e(statusLabels[r.status])}</td><td>${button('確認・再開','resumeGame',`data-id="${e(r.id)}"`,'light small')}${button('CSV出力','exportResult',`data-id="${e(r.id)}"`,'light small')}</td></tr>`).join('')}</tbody></table></div>`:'<div class="empty">まだゲームの記録がありません。</div>';}
 if(tab==='backup'){const backups=await api('backups');if(!$('backups-list'))return;$('backups-list').innerHTML=backups.length?backups.map(b=>`<div class="question-row"><div><h3>${e(b.status==='complete'?'保存完了':b.status==='expired'?'保存世代外':b.status==='running'?'保存中':'失敗')}</h3><p>${e(b.finishedAt||b.startedAt)}<br>${e(b.files??0)}ファイル / ${e(b.documents??0)}データ</p></div>${b.status==='complete'?button('テスト領域へ復元','restoreTest',`data-id="${e(b.id)}"`,'light small'):''}</div>`).join(''):'<p class="small-note">まだバックアップがありません。</p>';}}
async function poll(){if(config.backendReady===false||!['teacher','student','projector'].includes(role))return;if(polling||dialog.open)return;if(role==='teacher'&&tab!=='game')return;if(role==='student'&&!session)return;if(role==='projector'&&!currentGameId)return;polling=true;try{const data=await api(role==='teacher'?'teacherState':role==='projector'?'projectorState':'state',{gameId:role==='student'?session.gameId:currentGameId,token:role==='student'?session.token:teacherMeta[currentGameId]?.projectorToken});const rerender=!game||game.revision!==data.revision||!connection;serverOffset=data.serverNow-Date.now();game=data;connection=true;if(rerender)renderGame();else updateTimers();}catch(error){connection=false;const status=$('answer-status');if(status){status.textContent='通信が途切れています。下書きを保持して再接続しています。';status.className='answer-state error';}if(error.code==='SESSION'){toast(error.message,true);if(!dialog.open)openDialog('参加情報の確認',`<p class="muted">${e(error.message)}</p>${button('コードを入力し直す','leaveSession','','orange')}`);}}finally{polling=false;}}
function updateTimers(){const now=Date.now()+serverOffset;document.querySelectorAll('[data-deadline]').forEach(node=>{const ms=node.dataset.closed==='true'?0:node.dataset.paused!==''?Number(node.dataset.paused):Math.max(0,Number(node.dataset.deadline)-now),seconds=Math.ceil(ms/1000);node.textContent=Math.floor(seconds/60)+':'+String(seconds%60).padStart(2,'0');node.classList.toggle('urgent',seconds<=10);const bar=node.parentElement.querySelector('.progress span');if(bar)bar.style.width=Math.min(100,ms/Number(node.dataset.total)*100)+'%';if(seconds<=10&&seconds>0&&game?.status==='question'&&!muted){const key=game.round.id+':ten';if(audioKeys.has(key))return;audioKeys.add(key);tone([660,660,880],.12);}});document.querySelectorAll('[data-opening]').forEach(node=>node.textContent=Math.max(0,Math.ceil((Number(node.dataset.opening)-now)/1000)));}
const audioKeys=new Set();function tone(notes,duration=.16){if(muted||!audio)return;notes.forEach((frequency,i)=>{const osc=audio.createOscillator(),gain=audio.createGain();osc.type='sine';osc.frequency.value=frequency;gain.gain.value=0;osc.connect(gain);gain.connect(audio.destination);const start=audio.currentTime+i*duration;gain.gain.setValueAtTime(0,start);gain.gain.linearRampToValueAtTime(volume*.14,start+.01);gain.gain.exponentialRampToValueAtTime(.0001,start+duration);osc.start(start);osc.stop(start+duration+.01);});}
function playEvents(){if(!game)return;const stage=game.status+':'+game.index+':'+(game.round?.hint?'hint':'')+':'+(game.rankShown||0);if(stage===lastStage)return;lastStage=stage;if(game.status==='opening')tone([392,494,587,784],.2);else if(game.status==='question')tone(game.round.hint?[523,659]:[392,523],.2);else if(game.status==='closed')tone([440,330,220],.2);else if(game.status==='reveal')tone([523,659,784],.2);else if(game.status==='ranking')tone([440,554,659],.15);else if(game.status==='ended'){tone([523,659,784,1047],.25);if(!audioKeys.has('confetti:'+game.id)){audioKeys.add('confetti:'+game.id);for(let i=0;i<50;i++){const el=document.createElement('i');el.className='confetti';el.style.left=Math.random()*100+'vw';el.style.background=['#f0aa4b','#de7047','#75b5a3','#e9ebd2'][i%4];el.style.animationDelay=Math.random()+'s';document.body.appendChild(el);setTimeout(()=>el.remove(),5000);}}}}
function enableAudio(){muted=!muted;storage.set('muted',muted);if(!audio){audio=new(window.AudioContext||window.webkitAudioContext)();}audio.resume();if(!bgmTimer)bgmTimer=setInterval(()=>{if(game&&['opening','question','ranking'].includes(game.status))tone([196,247,294,247],.3);},4000);if(!muted)tone([523,659],.15);if(role==='home')renderHome();else if(game)renderGame();else if(role==='teacher')renderTeacher();else renderJoin();}
function csvParse(text){const rows=[],row=[];let value='',quoted=false;for(let i=0;i<text.length;i++){const c=text[i];if(c==='"'){if(quoted&&text[i+1]==='"'){value+='"';i++;}else quoted=!quoted;}else if(c===','&&!quoted){row.push(value);value='';}else if((c==='\n'||c==='\r')&&!quoted){if(c==='\r'&&text[i+1]==='\n')i++;row.push(value);if(row.some(v=>v!==''))rows.push([...row]);row.length=0;value='';}else value+=c;}if(value||row.length){row.push(value);rows.push(row);}if(quoted)throw Error('CSVの引用符が閉じられていません。');const columns=rows.shift()||[];return rows.map(r=>Object.fromEntries(columns.map((k,i)=>[k.trim(),r[i]||'']))).map(q=>({...q,acceptedAnswers:q.acceptedAnswers?JSON.parse(q.acceptedAnswers):[],sources:q.sources?JSON.parse(q.sources):[],hintThresholdSeconds:q.hintThresholdSeconds===''?null:Number(q.hintThresholdSeconds)}));}
function fileData(file){return new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(reader.result);reader.onerror=reject;reader.readAsDataURL(file);});}
function download(name,text,type='text/plain'){const blob=new Blob(['\uFEFF'+text],{type}),a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000);}
async function action(name,node){
 if(name==='closeDialog'){closeDialog();return;}
 if(name==='audio'){enableAudio();return;}
 if(name==='tab'){tab=node.dataset.tab;await refreshCatalog();renderTeacher();await loadAuxiliary();return;}
 if(name==='newQuestion'){questionForm();return;}
 if(name==='editQuestion'){questionForm(catalog.questions.find(q=>q.questionId===node.dataset.id));return;}
 if(name==='previewQuestion'){previewQuestion(node.dataset.id);return;}
 if(name==='questionPreviewMode'){previewQuestion(node.dataset.id,node.dataset.mode);return;}
 if(name==='questionAction'){const command=node.dataset.command;if(['approve','archive','reject'].includes(command)&&!confirm(command==='approve'?'正答の一意性、出典、画像の権利、類似問題を確認しました。この問題を承認しますか？':command==='archive'?'問題をアーカイブします。過去ゲームの内容は保持します。よろしいですか？':'この問題を非承認に変更しますか？'))return;await api('questionAction',{id:node.dataset.id,command});closeDialog();await refreshCatalog();renderTeacher();toast('問題を更新しました。');return;}
 if(name==='preset'){let preset;if(node.dataset.preset==='last'){preset=catalog.lastGameSettings;if(!preset){toast('前回の設定はまだありません。');return;}}else preset={...(selectionOptions||{}),count:node.dataset.preset==='10'?5:6,distribution:node.dataset.preset==='10'?{easy:3,standard:2,hard:0}:{easy:2,standard:2,hard:2},fields:['geography','history','civics'],units:[]};selectionOptions=preset;selected=[];renderTeacher();updateEstimate();return;}
 if(name==='moveSelected'){const i=Number(node.dataset.index),to=i+Number(node.dataset.dir);if(to>=0&&to<selected.length){[selected[i],selected[to]]=[selected[to],selected[i]];$('selection').innerHTML=selectionContent();}return;}
 if(name==='replaceSelected'||name==='addSelected'){const index=name==='addSelected'?-1:Number(node.dataset.index);const candidates=catalog.questions.filter(q=>q.approvalStatus==='approved'&&!q.archived&&q.reuseEnabled&&!selected.some(s=>s.questionId===q.questionId));openDialog(index<0?'問題を追加':'差し替える問題を選ぶ',candidates.length?candidates.map(q=>`<div class="question-row"><div>${badge(q)}<h3>${e(q.title)}</h3><p class="small-note">${e(q.unit)}</p></div>${button('選ぶ','chooseSelected',`data-id="${e(q.questionId)}" data-index="${index}"`,'orange small')}</div>`).join(''):'<div class="empty">選べる承認済み問題がありません。</div>');return;}
 if(name==='chooseSelected'){const q=catalog.questions.find(q=>q.questionId===node.dataset.id),i=Number(node.dataset.index);if(i<0)selected.push(q);else selected[i]=q;selectionApproval=true;closeDialog();$('selection').innerHTML=selectionContent();return;}
 if(name==='createGame'){if(!selected.length)throw Error('出題する問題を選んでください。');const alternativeApproved=$('alternative-approval')?.checked;if(selected.length!==selectionOptions.count&&!alternativeApproved)throw Error('問題数が設定と異なります。変更を確認して承認するか、候補を追加してください。');const result=await api('createGame',{...selectionOptions,questionIds:selected.map(q=>q.questionId),alternativeApproved});game=result.game;currentGameId=game.id;teacherMeta[game.id]={joinCode:result.joinCode,projectorToken:result.projectorToken};storage.set('teacherMeta',teacherMeta);storage.set('currentGameId',game.id);tab='game';serverOffset=game.serverNow-Date.now();renderGame();toast('ゲームを作成しました。問題を確認して参加受付を開いてください。');return;}
 if(name==='resumeGame'){currentGameId=node.dataset.id;storage.set('currentGameId',currentGameId);game=await api('teacherState',{gameId:currentGameId});tab='game';renderGame();return;}
 if(name==='command'){const command=node.dataset.command;if(command==='close'&&!confirm('今の回答で締め切りますか？'))return;if(command==='start'&&game.groups.some(g=>!g.joined)&&!confirm('まだ参加していない班があります。このまま開始しますか？'))return;game=await api('command',{gameId:currentGameId,command,seconds:Number(node.dataset.seconds)||undefined});renderGame();return;}
 if(name==='renewCode'||name==='renewProjection'){const result=await api(name==='renewCode'?'renewCode':'renewProjection',{gameId:currentGameId});teacherMeta[currentGameId]={...teacherMeta[currentGameId],...result};storage.set('teacherMeta',teacherMeta);await poll();renderGame();toast('再発行しました。以前のコード・リンクは失効します。');return;}
 if(name==='reassign'){if(!confirm('この班の端末を解除します。元の端末は操作できなくなります。新しい端末で参加し直してください。'))return;game=await api('command',{gameId:currentGameId,command:'reassign',groupId:node.dataset.id});renderGame();return;}
 if(name==='proxy'||name==='override'){const group=game.groups.find(g=>g.id===node.dataset.id);openDialog(e(group.name)+(name==='proxy'?'の代理回答':'の採点修正'),`<form id="${name}-form"><input type="hidden" name="groupId" value="${e(group.id)}">${name==='proxy'?'<label class="field">回答<input name="answer" required maxlength="2000"></label>':`<label class="field">対象の問題<select name="roundId">${game.rounds.map((r,i)=>`<option value="${e(r.id)}" ${i===game.index?'selected':''}>第${i+1}問 ${e(r.question.title)}</option>`).join('')}</select></label><label class="field">得点<input name="points" type="number" min="0" max="1000" value="${game.round?.results?.[group.id]?.points||0}" required></label><label class="inline"><input type="checkbox" name="isCorrect" ${game.round?.results?.[group.id]?.isCorrect?'checked':''}>正解として扱う</label>`}<label class="field" style="margin-top:18px">修正・救済の理由<textarea name="reason" required maxlength="1000"></textarea></label><p class="small-note">サーバーに監査履歴を残します。ヒント前得点を自動的にさかのぼって与えることはありません。</p><button class="btn orange">記録して反映</button></form>`);return;}
 if(name==='selectGroup'){selectedGroup=node.dataset.id;renderJoin();return;}
 if(name==='joinGroup'){if(!selectedGroup)throw Error('班を選んでください。');if(!confirm(`${joinInfo.className}・${joinInfo.groups.find(g=>g.id===selectedGroup).name}で参加しますか？`))return;session=await api('join',{code:joinInfo.code,groupId:selectedGroup});storage.set('session',session);feedback='';game=null;renderStudentWaiting();await poll();return;}
 if(name==='leaveSession'){if(!confirm('端末の参加情報を解除して、コード入力へ戻りますか？ サーバー側の班解除が必要な場合は先生に依頼してください。'))return;session=null;game=null;storage.remove('session');closeDialog();renderJoin();return;}
 if(name==='fullscreen'){if(document.fullscreenElement)await document.exitFullscreen();else await document.documentElement.requestFullscreen();return;}
 if(name==='zoomImage'){openDialog('問題資料を拡大',`<img alt="問題資料画像の拡大" src="${e(node.src)}" style="width:100%;max-height:75vh;object-fit:contain">`);return;}
 if(name==='activateYear'){if(!confirm('現在の年度を切り替えます。過年度のデータは保持します。よろしいですか？'))return;await api('activateYear',{id:node.dataset.id});await refreshCatalog();renderTeacher();return;}
 if(name==='importQuestions'){openDialog('JSON・CSVから一括取込',`<form id="import-form"><label class="field">ファイルを選択<input type="file" name="file" accept=".json,.csv"></label><label class="field">またはJSONを貼り付け<textarea name="json" style="min-height:180px" placeholder="問題オブジェクトの配列を貼り付け"></textarea></label><p class="small-note">最大200問。CSVのacceptedAnswers・sources列はJSONで記述します。出典はtitle / publisher / urlまたはdriveFileId / retrievedAt / licenseNotesを含めます。すべて未確認として取り込みます。</p><button class="btn orange">内容を検証して取り込む</button></form>`);return;}
 if(name==='questionImages'){const q=catalog.questions.find(q=>q.questionId===node.dataset.id);openDialog('問題の画像を管理',`<div class="image-list">${q.images.map((im,i)=>`<div>${images([im],'teacher')}<p class="small-note">${i+1}. ${e(im.altText)}</p>${button('↑','moveImage',`data-id="${e(q.questionId)}" data-file="${e(im.fileId)}" data-dir="-1"`,'light small')}${button('↓','moveImage',`data-id="${e(q.questionId)}" data-file="${e(im.fileId)}" data-dir="1"`,'light small')}${button('外す','detachImage',`data-id="${e(q.questionId)}" data-file="${e(im.fileId)}"`,'light small')}</div>`).join('')}</div><form id="image-form"><input type="hidden" name="questionId" value="${e(q.questionId)}"><label class="field" style="margin-top:20px">画像ファイル（PNG/JPEG/GIF/WebP、2MBまで）<input name="file" type="file" accept="image/png,image/jpeg,image/gif,image/webp" required></label><label class="field">代替テキスト<input name="altText" required></label><label class="field">利用条件・出典<input name="licenseNotes" required></label><button class="btn orange">アップロードして追加</button><p class="small-note">画像を変更した問題は未確認に戻ります。外したファイルも、参照が残る限り削除しません。</p></form>`);return;}
 if(name==='moveImage'||name==='detachImage'){const q=catalog.questions.find(q=>q.questionId===node.dataset.id),id=node.dataset.file;let input;if(name==='detachImage')input={questionId:q.questionId,fileId:id,command:'detach'};else{const order=q.images.map(i=>i.fileId),i=order.indexOf(id),to=i+Number(node.dataset.dir);if(to<0||to>=order.length)return;[order[i],order[to]]=[order[to],order[i]];input={questionId:q.questionId,command:'reorder',order};}await api('attachImage',input);await refreshCatalog();await action('questionImages',{dataset:{id:q.questionId}});return;}
 if(name==='manageFiles'){const files=await api('listFiles');openDialog('画像・参考資料ファイル',`<form id="source-file-form"><label class="field">参考資料（PDFは5MB・画像は2MBまで）<input type="file" name="file" accept="application/pdf,image/png,image/jpeg,image/webp,image/gif" required></label><label class="field">利用条件・資料名<input name="licenseNotes" required></label><button class="btn orange">非公開領域へ保存</button></form>${files.filter(f=>!f.deletedAt).map(f=>`<div class="question-row"><div><h3>${e(f.name)}</h3><p class="small-note">識別子 ${e(f.id)}<br>${e(f.licenseNotes)}</p></div>${button('削除','deleteFile',`data-id="${e(f.id)}"`,'light small')}</div>`).join('')}`);return;}
 if(name==='deleteFile'){if(!confirm('参照のないファイルを物理削除します。バックアップが必要な場合は先に保存してください。削除しますか？'))return;await api('deleteFile',{fileId:node.dataset.id,confirm:true});await action('manageFiles',node);return;}
 if(name==='backup'){node.disabled=true;toast('画像・設定を含めてバックアップしています…');const result=await api('backup');toast(result.skipped?'別のバックアップが実行中です。':'バックアップを保存しました。');await loadAuxiliary();return;}
 if(name==='restoreTest'){if(!confirm('本番を変更せず、隔離したテスト領域へ復元して内容を検証します。実行しますか？'))return;const result=await api('restoreTest',{id:node.dataset.id});openDialog('テスト復元・照合が完了',`<div class="notice good">${result.documents}データ / ${result.events}履歴 / ${result.files}ファイルを検証しました。本番は変更していません。</div><p class="small-note">復元識別子 ${e(result.id)}<br>検証日時 ${e(result.verifiedAt)}</p>`);return;}
 if(name==='gameHistory'){const rows=await api('responseHistory',{gameId:currentGameId});openDialog('回答・監査履歴',`<p class="small-note">ゲーム内の操作 ${game.audit?.length||0}件 / 回答履歴 ${rows.length}件</p><pre style="white-space:pre-wrap;overflow-wrap:anywhere;font-size:11px">${e(JSON.stringify({operations:game.audit,responses:rows},null,2))}</pre>`);return;}
 if(name==='previewGameRound'){const r=game.rounds[Number(node.dataset.index)];openDialog(r.question.title,`<h2>${e(r.question.body)}</h2>${images(r.question.images,'teacher')}<div class="reveal-answer">${e(r.question.primaryAnswer)}</div><div class="hint">${e(r.question.hintText)}</div><p class="explanation">${e(r.question.explanation)}</p>`);return;}
 if(name==='exportResult'){const result=await api('teacherState',{gameId:node.dataset.id});const escape=v=>'"'+String(v??'').replace(/"/g,'""').replace(/^[=+@-]/,"'$&")+'"';const lines=[['年度','クラス','班','得点','順位'],...result.scores.map(r=>[result.yearLabel,result.className,r.name,r.totalPoints,r.rank??''])];download('社会科クイズ結果.csv',lines.map(row=>row.map(escape).join(',')).join('\r\n'),'text/csv');return;}
}
async function submitForm(form){const f=new FormData(form),obj=Object.fromEntries(f.entries());
 if(form.id==='year-form'){const classes=obj.classes.split(/\r?\n/).filter(v=>v.trim()).map(line=>{const match=/^(.+?)\s*[:：]\s*(\d+)\s*$/.exec(line);if(!match)throw Error('クラスは「3年1組:8」の形式で記入してください。');return{name:match[1].trim(),groupCount:Number(match[2])}});await api('createYear',{...obj,classes});await refreshCatalog();renderTeacher();toast('年度・クラスを追加しました。');}
 if(form.id==='settings-form'){const input={};for(const key of ['openingSeconds','explanationSeconds','transitionSeconds','rankingSeconds','volume'])input[key]=Number(obj[key]);input.muted=f.has('muted');input.hintRemainingSeconds=Object.fromEntries(['easy','standard','hard'].map(d=>[d,Number(obj['hint-'+d])]));await api('settings',input);muted=input.muted;volume=input.volume;storage.set('muted',muted);storage.set('volume',volume);await refreshCatalog();renderTeacher();toast('設定を保存しました。');}
 if(form.id==='backup-settings'){await api('settings',{backupEnabled:f.has('backupEnabled'),backupIntervalHours:Number(obj.backupIntervalHours),backupRetention:Number(obj.backupRetention)});await refreshCatalog();renderTeacher();await loadAuxiliary();toast('設定を保存しました。');}
 if(form.id==='question-form'){const sources=obj.sources.split(/\r?\n/).filter(x=>x.trim()).map(line=>JSON.parse(line));const q={...obj,questionId:obj.questionId||undefined,sources,acceptedAnswers:obj.acceptedAnswers.split(/\r?\n/).filter(x=>x.trim()),reuseEnabled:f.has('reuseEnabled'),hintThresholdSeconds:obj.hintThresholdSeconds===''?null:Number(obj.hintThresholdSeconds)};await api('saveQuestion',q);closeDialog();await refreshCatalog();renderTeacher();toast('未確認として保存しました。');}
 if(form.id==='game-setup'){selectionOptions={yearId:obj.yearId,classId:obj.classId,isSimulation:f.has('isSimulation'),count:Number(obj.count),fields:f.getAll('fields'),units:obj.units.split(',').map(v=>v.trim()).filter(Boolean),distribution:Object.fromEntries(['easy','standard','hard'].map(d=>[d,Number(obj[d])]))};if(Object.values(selectionOptions.distribution).reduce((s,n)=>s+n,0)!==selectionOptions.count)throw Error('難易度配分の合計を問題数と合わせてください。');const result=await api('preview',selectionOptions);selected=result.selected;selectionApproval=result.requiresApproval;$('selection').innerHTML=selectionContent();$('selection').scrollIntoView({behavior:'smooth',block:'start'});}
 if(form.id==='join-code-form'){const code=obj.code.replace(/\s/g,'');joinInfo={...await api('join',{code,lookup:true}),code};selectedGroup=null;renderJoin();}
 if(form.id==='answer-form'){const answer=$('student-answer').value;let pending=storage.get('pending:'+game.round.id);if(!pending||pending.answer!==answer)pending={requestId:crypto.randomUUID(),answer,roundId:game.round.id};storage.set('pending:'+game.round.id,pending);storage.set('draft:'+game.round.id,answer);feedback='送信中…';$('answer-status').textContent=feedback;try{const receipt=await api('submit',{...pending,gameId:session.gameId,token:session.token});storage.remove('pending:'+game.round.id);feedback=receipt.accepted?'サーバー受理済み：'+new Date(receipt.serverReceivedAt).toLocaleTimeString('ja-JP',{timeZone:'Asia/Tokyo'}):'締切後または停止中のため受理されませんでした。先生に確認してください。';$('answer-status').textContent=feedback;await poll();}catch(error){feedback='失敗：通信状態を確認して再送してください。下書きと送信IDを保持しています。';$('answer-status').textContent=feedback;throw error;}}
 if(form.id==='proxy-form'||form.id==='override-form'){game=await api('command',{gameId:currentGameId,command:form.id==='proxy-form'?'proxy':'overrideScore',...obj,points:obj.points===undefined?undefined:Number(obj.points),isCorrect:f.has('isCorrect')});closeDialog();renderGame();toast('理由とともに記録しました。');}
 if(form.id==='import-form'){const file=f.get('file');let text=file?.size?await file.text():obj.json;let questions=file?.name?.toLowerCase().endsWith('.csv')?csvParse(text):JSON.parse(text);if(!Array.isArray(questions))questions=questions.questions||[questions];const result=await api('importQuestions',{questions});closeDialog();await refreshCatalog();tab='bank';renderTeacher();toast(result.length+'問を未確認で取り込みました。');}
 if(form.id==='image-form'||form.id==='source-file-form'){const file=f.get('file');if(!file?.size)throw Error('ファイルを選択してください。');const result=await api('uploadFile',{data:await fileData(file),name:file.name,licenseNotes:obj.licenseNotes});if(form.id==='image-form'){await api('attachImage',{questionId:obj.questionId,fileId:result.id,altText:obj.altText,licenseNotes:obj.licenseNotes,command:'attach'});await refreshCatalog();await action('questionImages',{dataset:{id:obj.questionId}});}else{toast('資料を保存しました。識別子を出典に記録してください。');await action('manageFiles',form);}}
}
document.addEventListener('click',async event=>{const node=event.target.closest('[data-action]');if(!node)return;event.preventDefault();const wasDisabled=node.disabled;node.disabled=true;try{await action(node.dataset.action,node)}catch(error){toast(error.message,true)}finally{if(node.isConnected)node.disabled=wasDisabled;}});
document.addEventListener('submit',async event=>{event.preventDefault();const form=event.target;const button=form.querySelector('button[type=submit],button:not([type])');if(button)button.disabled=true;try{await submitForm(form)}catch(error){toast(error.message,true)}finally{if(button?.isConnected)button.disabled=false;}});
document.addEventListener('input',event=>{const node=event.target;if(node.id==='student-answer'&&game?.round)storage.set('draft:'+game.round.id,node.value);if(node.closest('#game-setup'))updateEstimate();if(node.id==='bank-search'){bankFilter=node.value;clearTimeout(bankContent.timer);bankContent.timer=setTimeout(()=>{const pos=node.selectionStart;renderTeacher();$('bank-search').focus();$('bank-search').setSelectionRange(pos,pos)},300);}});
document.addEventListener('change',event=>{if(event.target.id==='yearSelect'){const year=catalog.years.find(y=>y.id===event.target.value);$('classSelect').innerHTML=year.classes.map(k=>`<option value="${e(k.id)}">${e(k.name)}</option>`).join('');}if(event.target.id==='bank-field'){filterField=event.target.value;renderTeacher();}if(event.target.id==='bank-approval'){filterApproval=event.target.value;renderTeacher();}});
window.addEventListener('online',()=>{toast('接続が復旧しました。サーバー状態を確認します。');poll();});window.addEventListener('offline',()=>{connection=false;toast('オフラインです。下書きを保持しています。',true)});
setInterval(poll,3000);setInterval(updateTimers,250);
if(config.backendReady===false&&role!=='home'){shell('<div class="join-page"><section class="panel"><h1>サーバーの公開を準備しています。</h1><p class="muted">画面と主要機能のコードは準備済みです。回答保存・採点サーバーの公開処理が実行権限により停止しているため、まだゲームを開始できません。</p><a class="btn orange" href="./">トップページを見る</a></section></div>');return;}
if(role==='teacher'){await loadTeacher();await loadAuxiliary();}else if(role==='student'){renderJoin();if(session)await poll();}else if(role==='projector'){shell('<div class="waiting"><h1>投影画面を接続しています…</h1><p class="muted">先生用画面の「投影画面を開く」から接続してください。</p></div>');await poll();}else{role='home';renderHome();}
})();
